package edu.gatech.erms.api.dto;

import edu.gatech.erms.service.CreateIncidentCommand;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * {@code POST /api/v1/incidents} body. The incident id is generated by the server. "Date not after
 * today" and "declaration exists" are checked by the service.
 */
public record CreateIncidentRequest(
    @NotBlank @Size(max = 2) String declarationAbbreviation,
    @NotNull LocalDate incidentDate,
    @NotBlank @Size(min = 6, max = 500) String description,
    @NotNull @DecimalMin("-90") @DecimalMax("90") BigDecimal latitude,
    @NotNull @DecimalMin("-180") @DecimalMax("180") BigDecimal longitude) {

  public CreateIncidentCommand toCommand() {
    return new CreateIncidentCommand(
        declarationAbbreviation, incidentDate, description, latitude, longitude);
  }
}
